import { useEffect } from 'react'

const PaymentPlans = () => {
  useEffect(() => {
    // Check if script already exists
    if (document.getElementById('cherry-widget-script')) {
      return
    }

    // Create and load Cherry widget script
    const script = document.createElement('script')
    script.id = 'cherry-widget-script'
    script.src = 'https://files.withcherry.com/widgets/widget.js'
    script.async = true

    script.onload = () => {
      // Wait for _hw to be available
      const initWidget = () => {
        if (typeof window._hw === 'function') {
          window._hw(
            'init',
            {
              debug: false,
              variables: {
                slug: 'excelaestheticsmiami',
                name: 'Excel Aesthetics',
              },
              styles: {
                primaryColor: '#F3BA64',
                secondaryColor: '#FFFAF1',
                fontFamily: 'Alice',
              },
            },
            ['all', 'hero', 'howitworks', 'testimony', 'faq', 'calculator']
          )
        } else {
          setTimeout(initWidget, 100)
        }
      }
      initWidget()
    }

    document.body.appendChild(script)

    return () => {
      // Cleanup on unmount
      const existingScript = document.getElementById('cherry-widget-script')
      if (existingScript) {
        document.body.removeChild(existingScript)
      }
      // Clear widget content
      const widgetContainer = document.getElementById('all')
      if (widgetContainer) {
        widgetContainer.innerHTML = ''
      }
    }
  }, [])

  return (
    <section
      id='payment-plans'
      className='min-h-screen bg-neutral-950 pt-32 pb-24'
    >
      <div className='container mx-auto px-6'>
        {/* Page Header */}
        <div className='text-center max-w-3xl mx-auto mb-16'>
          <h1 className='text-4xl md:text-5xl lg:text-6xl font-normal text-neutral-100 mb-6 uppercase tracking-tight'>
            Payment <span className='text-amber-600'>Plans</span>
          </h1>
          <p className='text-base text-neutral-400 leading-relaxed'>
            We believe everyone deserves access to quality aesthetic treatments.
            That's why we offer flexible financing options through CareCredit
            and Cherry to help you achieve your beauty goals.
          </p>
        </div>

        {/* CareCredit Section */}
        <div className='max-w-5xl mx-auto mb-16'>
          <div className='bg-teal-700 border border-teal-600 p-8 md:p-12 grid grid-cols-2 md:grid-cols-1 gap-8 items-center'>
            <div className='flex justify-center md:justify-start'>
              <div className='bg-white p-6 rounded-lg'>
                <img
                  src='https://www.carecredit.com/assets/social/carecredit-share.png'
                  alt='CareCredit'
                  className='h-20 w-auto'
                />
              </div>
            </div>
            <div>
              <h2 className='text-3xl font-normal text-white mb-4'>
                Now accepting CareCredit for your convenience!
              </h2>
              <p className='text-white/90 mb-6'>
                CareCredit is a healthcare credit card that can be used for
                medical expenses not covered by insurance. Apply today and get
                approved in minutes.
              </p>
              <button
                onClick={() =>
                  window.open('https://www.carecredit.com/apply/', '_blank')
                }
                className='bg-amber-600 hover:bg-amber-500 text-neutral-950 px-8 py-3 uppercase tracking-wider text-sm font-semibold transition-colors'
              >
                Apply Now
              </button>
            </div>
          </div>
        </div>

        {/* Cherry Widget Container */}
        <div className='max-w-6xl mx-auto'>
          <style>{`
            #all {
              margin-top: 50px;
              margin-bottom: 50px;
            }
          `}</style>
          <div id='all'></div>
        </div>

        {/* Additional Info */}
        <div className='max-w-3xl mx-auto mt-16 text-center'>
          <h3 className='text-2xl font-normal text-neutral-100 mb-4 uppercase tracking-wide'>
            Have Questions?
          </h3>
          <p className='text-neutral-400 mb-8'>
            Our team is here to help you understand your financing options and
            choose the best payment plan for your needs.
          </p>
          <a
            href='#contact'
            className='inline-block border-2 border-amber-600 text-amber-600 hover:bg-amber-600 hover:text-neutral-950 px-8 py-3 uppercase tracking-wider text-sm font-semibold transition-all'
          >
            Contact Us
          </a>
        </div>
      </div>
    </section>
  )
}

export default PaymentPlans
